// Checkout handler with paidEvent logging
const { logEvent } = require('./eventLogger');

async function handleCheckout(req, res) {
  try {
    const { userId, plan, amount, currency } = req.body;
    // Simulate payment processing
    const paymentSuccess = true; // Replace with actual payment gateway call
    if (paymentSuccess) {
      await logEvent('paidEvent', { userId, plan, amount, currency, timestamp: new Date().toISOString() });
      res.status(200).json({ status: 'success', message: 'Payment processed' });
    } else {
      res.status(402).json({ status: 'failed', message: 'Payment declined' });
    }
  } catch (err) {
    console.error('Checkout error:', err);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
}

module.exports = { handleCheckout };
